-- Bundled boss facts: what the addon knows about the bosses of its recommended plans without any other addon.
-- IDs and numbers only (npc, creature display, level, classification, ability spell IDs with a tag and an optional short
-- note, drop item IDs, dungeon quest IDs); the game supplies names, icons and descriptions of spells and items.
-- The data files are Data/Bosses/<slug>.lua, generated by tools/gen_bosses.lua from data-src/bosses/*.json; sources
-- and licences in docs/DATA-SOURCES.md. Pure Lua except for the optional Loot.SlotOf call.
--
-- The functions have the shape of the Dungeon Journal adapter (Data/Providers/DungeonJournal.lua) so Data/BossInfo.lua
-- and the portraits can use this data first and take a provider's answer as an addition:
--   BossData.Boss(plan, enc)      -> { level = "20" | "24-25" | "??", rare?, class?, npcID?, drops?, abilities? } | nil
--   BossData.Loot(plan, enc)      -> { { itemID, slot?, notable? }, ... } | nil
--   BossData.Portrait(plan, enc)  -> { displayInfo = id } | nil
--   BossData.Abilities(plan, enc, max?) -> { { spellID, tags = { "interrupt", ... }, note? }, ... } | nil
--   BossData.Quests(plan)         -> { { questID, name, level?, req?, side?, giver?, items? }, ... } | nil
--   BossData.Keys(plan)           -> { { itemID? | questID?, name, kind, required, side, quests?, alt?, group?, note?,
--                                      forever }, ... }
--   BossData.Credit               the sources, for "Sources: ..." lines

local _, ns = ...
local BossData = ns:NewModule("BossData")

BossData.Credit = "Wowhead, warcraft.wiki.gg"
BossData.MAX_ABILITIES = 8
BossData.MAX_DROPS = 16
BossData.enabled = true -- tests of the provider path switch it off (the bundled data would answer first)

local list = {} -- added data tables, in load order
local index -- [instance key] = data, built on first use

local CLASS = { n = "normal", e = "elite", re = "rareelite", wb = "worldboss", r = "rare" }
local SIDE = { a = "alliance", h = "horde", b = "both" }

function BossData.Add(raw)
	if type(raw) == "table" and type(raw.name) == "string" and type(raw.bosses) == "table" then
		list[#list + 1] = raw
		index = nil
	end
end

local function key(name)
	return ns.Providers and ns.Providers.Key(name) or nil
end

local function byInstance()
	if not index then
		index = {}
		for _, d in ipairs(list) do
			local k = key(d.name)
			if k and not index[k] then
				index[k] = d
			end
		end
	end
	return index
end

-- The data table of a plan's instance (matched by instance name, like the providers do), or nil.
function BossData.Instance(plan)
	if not BossData.enabled then
		return nil
	end
	local k = ns.Providers and ns.Providers.PlanKey(plan)
	return k and byInstance()[k] or nil
end

local function same(a, b)
	return ns.Match.StripArticle(a) == b
end

-- The entry of a boss by the name of a plan encounter; "A / B" names match either part.
function BossData.Entry(plan, enc)
	local d = BossData.Instance(plan)
	local want = ns.Providers and ns.Providers.BossKey(enc)
	if not d or not want then
		return nil
	end
	for _, b in ipairs(d.bosses) do
		if same(b.name, want) then
			return b, d
		end
	end
	for _, b in ipairs(d.bosses) do
		for part in b.name:gmatch("[^/]+") do
			if same(part:match("^%s*(.-)%s*$"), want) then
				return b, d
			end
		end
	end
	return nil
end

function BossData.LevelText(b)
	local lv = b.lv
	if lv == "??" then
		return "??"
	elseif type(lv) == "table" and lv[1] then
		return lv[1] == lv[2] and tostring(lv[1]) or (lv[1] .. "-" .. lv[2])
	end
	return nil
end

local function drops(b, max)
	if type(b.loot) ~= "table" then
		return nil
	end
	local notable = {}
	for _, id in ipairs(b.notable or {}) do
		notable[id] = true
	end
	local out = {}
	for _, id in ipairs(b.loot) do
		if #out >= (max or BossData.MAX_DROPS) then
			break
		end
		out[#out + 1] = { itemID = id, slot = ns.Loot and ns.Loot.SlotOf(id) or nil, notable = notable[id] or nil }
	end
	return #out > 0 and out or nil
end

local function abilities(b, max)
	if type(b.ab) ~= "table" then
		return nil
	end
	local out = {}
	for _, a in ipairs(b.ab) do
		if #out >= (max or BossData.MAX_ABILITIES) then
			break
		end
		local tags = {}
		if type(a[2]) == "string" then
			for t in a[2]:gmatch("[^,]+") do
				tags[#tags + 1] = t
			end
		end
		out[#out + 1] = { spellID = a[1], tags = tags, note = type(a[3]) == "string" and a[3] or nil }
	end
	return #out > 0 and out or nil
end

function BossData.Loot(plan, enc)
	local b = BossData.Entry(plan, enc)
	return b and drops(b) or nil
end

function BossData.Portrait(plan, enc)
	local b = BossData.Entry(plan, enc)
	if b and type(b.disp) == "number" then
		return { displayInfo = b.disp }
	end
	return nil
end

function BossData.Abilities(plan, enc, max)
	local b = BossData.Entry(plan, enc)
	return b and abilities(b, max) or nil
end

-- What the bundled data states about one boss, nil when it states nothing.
function BossData.Boss(plan, enc)
	local b = BossData.Entry(plan, enc)
	if not b then
		return nil
	end
	local cls = CLASS[b.cls]
	local info = { level = BossData.LevelText(b), rare = (cls == "rare" or cls == "rareelite") or nil,
		class = cls, npcID = b.npc, drops = drops(b), abilities = abilities(b) }
	if next(info) == nil then
		return nil
	end
	return info
end

function BossData.Quests(plan)
	local d = BossData.Instance(plan)
	if not d or type(d.quests) ~= "table" then
		return nil
	end
	local out = {}
	for _, q in ipairs(d.quests) do
		out[#out + 1] = { questID = q.id, name = q.name, level = q.lv, req = q.req, side = SIDE[q.side or "b"],
			giver = q.giver, items = q.items }
	end
	return #out > 0 and out or nil
end

-- Keys and attunements of the plan's instance (an item to carry or a quest to have done), required ones first.
function BossData.Keys(plan)
	local d = BossData.Instance(plan)
	if not d or type(d.keys) ~= "table" then
		return nil
	end
	local out = {}
	for _, k in ipairs(d.keys) do
		out[#out + 1] = { itemID = k.item, questID = k.quest, name = k.name, kind = k.kind, required = k.req == true,
			side = SIDE[k.side or "b"], quests = k.quests, alt = k.alt, group = k.group, note = k.note,
			forever = k.fv == true }
	end
	return #out > 0 and out or nil
end

function BossData.Counts()
	local c = { instances = #list, bosses = 0, abilities = 0, drops = 0, quests = 0 }
	for _, d in ipairs(list) do
		for _, b in ipairs(d.bosses) do
			c.bosses = c.bosses + 1
			c.abilities = c.abilities + #(b.ab or {})
			c.drops = c.drops + #(b.loot or {})
		end
		c.quests = c.quests + #(d.quests or {})
	end
	return c
end
